 private boolean isDark(){String p=getSharedPreferences("appearance",0).getString("theme","system");return p.equals("dark")||(p.equals("system")&&(getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES);}
 private void applyAppearance(){boolean dark=isDark();int background=dark?0xff111a15:0xfff8f9f6,ink=dark?0xffe4eddf:0xff283830;setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);getWindow().setStatusBarColor(background);getWindow().setNavigationBarColor(background);getWindow().getDecorView().setSystemUiVisibility(dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(root!=null)root.setBackgroundColor(background);if(toolbar!=null)toolbar.setBackgroundColor(background);if(web!=null)web.setBackgroundColor(background);for(Button b:new Button[]{home,widgets,connect})if(b!=null){b.setTextColor(ink);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?0xff26382b:0xffeaf0e2));}}
 private void loadLocal(String path){web.loadUrl(LOCAL+"/"+safePath(path));}
 static String safePath(String path){return path!=null&&(path.matches("\\?page=(today|library|activity|settings|coach)")||path.matches("\\?resource=[a-zA-Z0-9_-]{1,100}"))?path:"";}
 static boolean allowed(Uri u){return "https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost());}
 private WebResourceResponse assetResponse(Uri uri){try{if(!allowed(uri))return resourceError(403,"Blocked");String path=uri.getPath();if(path==null||path.equals("/"))path="/index.html";if(path.contains("..")||path.contains("\\")||path.contains("\u0000"))return resourceError(404,"Not found");String mime=path.endsWith(".html")?"text/html":path.endsWith(".js")||path.endsWith(".mjs")?"text/javascript":path.endsWith(".css")?"text/css":path.endsWith(".svg")?"image/svg+xml":"application/octet-stream";Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-cache");headers.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,getAssets().open("dashboard"+path));}catch(Exception e){return resourceError(404,"Not found");}}
 private WebResourceResponse resourceError(int status,String text){return new WebResourceResponse("text/plain","UTF-8",status,text,new HashMap<>(),new ByteArrayInputStream(text.getBytes()));}
 private void requireLocal(){if(!trustedPage)throw new SecurityException("Local dashboard only");}
 private String error(String message){try{return new JSONObject().put("error",message).toString();}catch(Exception e){return "{}";}}
 class Bridge {
  @JavascriptInterface public void updateAppearance(String theme){requireLocal();if(!Arrays.asList("light","dark","system").contains(theme))return;getSharedPreferences("appearance",0).edit().putString("theme",theme).apply();handler.post(()->{applyAppearance();LearningWidget.updateAll(MainActivity.this);});}
  @JavascriptInterface public String loadLibrary(){requireLocal();try{return library.read();}catch(Exception e){return error("Local library could not be read. Export backups before resetting app data.");}}
  @JavascriptInterface public String saveLibrary(String value){requireLocal();try{return library.save(value);}catch(Exception e){return error("Could not save on this phone. Check free storage.");}}
  @JavascriptInterface public String readPreference(String key){requireLocal();if(!Arrays.asList("wifi","wifi-base","wifi-last").contains(key))return "";return getSharedPreferences("local_preferences",0).getString(key,"");}
  @JavascriptInterface public void writePreference(String key,String value){requireLocal();if(!Arrays.asList("wifi","wifi-base","wifi-last").contains(key)||value==null||value.length()>4000000)throw new IllegalArgumentException();getSharedPreferences("local_preferences",0).edit().putString(key,value).commit();}
  @JavascriptInterface public String pendingBackup(){requireLocal();try{File f=new File(getCacheDir(),"pending-backup.json");return f.exists()?new String(java.nio.file.Files.readAllBytes(f.toPath()),"UTF-8"):"";}catch(Exception e){return "";}}
  @JavascriptInterface public void clearPendingBackup(){requireLocal();new File(getCacheDir(),"pending-backup.json").delete();}
  @JavascriptInterface public String aiSettings(){requireLocal();try{return keys.settings();}catch(Exception e){return error("Could not read the encrypted AI key. Remove it and save a new key.");}}
  @JavascriptInterface public String saveAiKey(String key,String model){requireLocal();try{keys.save(key,model);return "{\"saved\":true}";}catch(Exception e){return error("Could not encrypt the key on this phone.");}}
  @JavascriptInterface public void removeAiKey(){requireLocal();keys.remove();}
  @JavascriptInterface public void requestOpenAI(String id,String body){requireLocal();if(body==null||body.length()>200000){reply(id,413,error("AI input is too large"));return;}network.execute(()->{try{String key=keys.key();if(key.isEmpty())throw new Exception();JSONObject data=new JSONObject(body);data.put("model",keys.model());data.put("store",false);request(id,"https://api.openai.com/v1/responses","POST",data.toString(),key,true);}catch(Exception e){reply(id,503,error("Save your OpenAI key in Settings. AI needs an internet connection."));}});}
  @JavascriptInterface public void testAiKey(String id){requireLocal();network.execute(()->{try{request(id,"https://api.openai.com/v1/models","GET",null,keys.key(),true);}catch(Exception e){reply(id,503,error("OpenAI could not be reached. Check your key and internet connection."));}});}
  @JavascriptInterface public void requestLan(String id,String raw){requireLocal();if(raw==null||raw.length()>4500000){reply(id,413,error("Library is too large"));return;}network.execute(()->{try{JSONObject j=new JSONObject(raw);String address=LanAddress.validate(j.getString("address")),method=j.getString("method"),code=j.getString("code");if(!j.getString("path").equals("/lan/state")||!Arrays.asList("GET","PUT").contains(method)||!code.matches("[a-zA-Z0-9_-]{32,128}"))throw new Exception();request(id,address+"/lan/state",method,j.optString("body"),code,false);}catch(Exception e){reply(id,503,error("Computer unavailable. Your phone library is safe."));}});}
  @JavascriptInterface public void updateWidgets(String json){requireLocal();handler.post(()->{try{WidgetStore.save(MainActivity.this,json);LearningWidget.updateAll(MainActivity.this);}catch(Exception ignored){}});}
  @JavascriptInterface public void exportFile(String name,String contents){requireLocal();if(contents==null||contents.length()>4000000||name==null||!name.matches("[a-zA-Z0-9._-]{1,120}"))return;try{try(FileOutputStream out=new FileOutputStream(new File(getCacheDir(),"pending-export.json"))){out.write(contents.getBytes("UTF-8"));}handler.post(()->{Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(save,31);});}catch(Exception ignored){}}
  @JavascriptInterface public boolean cacheBook(String id,String name){requireLocal();try{if(pickedBook==null||!pickedName.equals(name))return false;BookFiles.save(MainActivity.this,id,name,pickedBook);return true;}catch(Exception e){return false;}}
  @JavascriptInterface public boolean openBook(String id){requireLocal();if(!BookFiles.file(MainActivity.this,id).exists())return false;handler.post(()->{if(!BookFiles.open(MainActivity.this,id))Toast.makeText(MainActivity.this,"No reading app could open this file.",Toast.LENGTH_LONG).show();});return true;}
 }
 private void request(String id,String url,String method,String body,String token,boolean openai)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(8000);connection.setReadTimeout(openai?45000:10000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+token);connection.setRequestProperty("Content-Type","application/json");try{if(method.equals("POST")||method.equals("PUT")){connection.setDoOutput(true);try(OutputStream out=connection.getOutputStream()){out.write((body==null?"":body).getBytes("UTF-8"));}}int status=connection.getResponseCode();if(status>=300&&openai){reply(id,502,error("OpenAI rejected the request. Check the key, model, permissions, and account quota."));return;}InputStream stream=status>=400?connection.getErrorStream():connection.getInputStream();String response=readBounded(stream,openai?500000:4000000);if(openai&&method.equals("GET")&&status==200)response="{\"valid\":true,\"message\":\"Connection verified without generating a model response.\"}";reply(id,status,response);}finally{connection.disconnect();}}
 private String readBounded(InputStream in,int max)throws Exception{if(in==null)return "{}";try(InputStream stream=in;ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=stream.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>max)throw new IOException("Response too large");}return bytes.toString("UTF-8");}}
 private void reply(String id,int status,String body){if(id==null||!id.matches("[a-zA-Z0-9-]{1,100}"))return;handler.post(()->{if(!trustedPage)return;try{JSONObject detail=new JSONObject().put("id",id).put("status",status).put("body",body);web.evaluateJavascript("window.dispatchEvent(new CustomEvent('learning-native-response',{detail:"+detail.toString()+"}))",null);}catch(Exception ignored){}});}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==21&&fileCallback!=null){pickedBook=null;pickedName="";if(result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();try(Cursor cursor=getContentResolver().query(uri,new String[]{"_display_name"},null,null,null)){if(cursor!=null&&cursor.moveToFirst())pickedName=cursor.getString(0);}if(pickedName.toLowerCase().matches(".*\\.(pdf|epub)$"))pickedBook=uri;fileCallback.onReceiveValue(new Uri[]{uri});}else fileCallback.onReceiveValue(null);fileCallback=null;}if(req==22&&result==RESULT_OK&&data!=null)importUri(data.getData());if(req==31&&result==RESULT_OK&&data!=null){try(InputStream in=new FileInputStream(new File(getCacheDir(),"pending-export.json"));OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);Toast.makeText(this,"Backup saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not export. Try another location.",Toast.LENGTH_LONG).show();}}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(!importIntent(intent))loadLocal(safePath(intent.getStringExtra("path")));}
 private boolean importIntent(Intent intent){Uri u=null;if(Intent.ACTION_SEND.equals(intent.getAction()))u=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null){importUri(u);loadLocal("");return true;}return false;}
 private void importUri(Uri uri){try{String value=readBounded(getContentResolver().openInputStream(uri),4000000);JSONObject parsed=new JSONObject(value);if(parsed.has("resources")&&parsed.getInt("version")==1){try(FileOutputStream out=new FileOutputStream(new File(getCacheDir(),"pending-backup.json"))){out.write(value.getBytes("UTF-8"));}loadLocal("?page=settings");}else{WidgetStore.save(this,value);LearningWidget.updateAll(this);Toast.makeText(this,"Widgets updated",Toast.LENGTH_SHORT).show();}}catch(Exception e){new AlertDialog.Builder(this).setTitle("Choose a library backup or widget snapshot").setMessage("Course JSON imports use Add to library → File inside the dashboard.").setPositiveButton("OK",null).show();}}
 private void showWidgets(){String[] names={"Learning overview · 4×2","Today’s plan · 4×2","Streak · 3×2","Daily goal · 2×1","Next lesson · 4×1","Reading · 2×2","Weekly rhythm · 4×2","Refresh from the local app","Open hosted dashboard in browser"};new AlertDialog.Builder(this).setTitle("Your learning, at a glance").setItems(names,(d,which)->{if(which<7){Class<?>[] types={OverviewWidget.class,TodayWidget.class,StreakWidget.class,GoalWidget.class,NextWidget.class,ReadingWidget.class,WeekWidget.class};android.appwidget.AppWidgetManager m=android.appwidget.AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,types[which]),null,null);else Toast.makeText(this,"Long press home screen → Widgets → Learning Space",Toast.LENGTH_LONG).show();}else if(which==7)loadLocal("?page=today");else startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(ORIGIN)));}).show();}
